var w = RulesEngine.get_unit_weapons("U_BATTLEWAGON_G", GameState.state)
var ids = []
for mid in w:
	for i in w[mid]:
		if i not in ids: ids.append(i)
ids.sort()
return ",".join(ids)

var wt = tree.current_scene.get_node("ShootingController").weapon_tree
var c = wt.get_root().get_first_child()
var names = []
while c:
	names.append(c.get_text(0))
	c = c.get_next()
return " | ".join(names)

var wt = tree.current_scene.get_node("ShootingController").weapon_tree
var c = wt.get_root().get_first_child()
var txt = ""
while c:
	txt += c.get_text(0) + " "
	c = c.get_next()
return txt.to_lower().contains("kannon") and txt.to_lower().contains("lobba")

